INSERT IGNORE INTO `heritage_records` (`id`, `title`, `category_id`, `summary`, `description`, `cultural_significance`, `community`, `language`, `source`, `period`, `date_recorded`, `keywords`, `location`, `location_is_sensitive`, `visibility`, `status`, `is_sacred`, `consent_status`, `consent_given_by`, `consent_date`, `consent_notes`, `created_by`, `updated_by`, `approved_by`, `approved_at`, `published_at`, `legacy_source`, `legacy_id`, `created_at`, `updated_at`) VALUES (7, 'Bamboo', 7, NULL, 'Fast-growing grass known for its strength and flexibility. Indigenous communities have used bamboo for centuries in construction, crafts, and daily tools.\n\nTraditional uses: Construction, weaving, tools, musical instruments', 'Represents resilience and adaptability. Sacred in many indigenous cultures as a symbol of longevity.', NULL, NULL, NULL, NULL, NULL, 'Traditional material, Construction, weaving, tools, musical instruments', NULL, 1, 'public', 'published', 0, 'pending', NULL, NULL, 'Migrated from the earlier public portal, where it was already publicly displayed. Community consent has not been documented yet; please review and update.', NULL, NULL, NULL, NULL, '2026-09-07 08:41:19', 'materials', 1, '2026-09-07 08:41:19', '2026-10-13 23:50:56');
INSERT IGNORE INTO `heritage_records` (`id`, `title`, `category_id`, `summary`, `description`, `cultural_significance`, `community`, `language`, `source`, `period`, `date_recorded`, `keywords`, `location`, `location_is_sensitive`, `visibility`, `status`, `is_sacred`, `consent_status`, `consent_given_by`, `consent_date`, `consent_notes`, `created_by`, `updated_by`, `approved_by`, `approved_at`, `published_at`, `legacy_source`, `legacy_id`, `created_at`, `updated_at`) VALUES (8, 'Rattan', 7, NULL, 'Palm vine used extensively in furniture making and basket weaving. Its natural flexibility makes it ideal for creating durable yet lightweight items.\n\nTraditional uses: Furniture, baskets, crafts, binding', 'Symbolizes the interconnectedness of all living things. Harvested sustainably to maintain forest balance.', NULL, NULL, NULL, NULL, NULL, 'Traditional material, Furniture, baskets, crafts, binding', NULL, 1, 'public', 'published', 0, 'pending', NULL, NULL, 'Migrated from the earlier public portal, where it was already publicly displayed. Community consent has not been documented yet; please review and update.', NULL, NULL, NULL, NULL, '2026-09-07 08:41:19', 'materials', 2, '2026-09-07 08:41:19', '2026-10-13 23:50:56');
INSERT IGNORE INTO `heritage_records` (`id`, `title`, `category_id`, `summary`, `description`, `cultural_significance`, `community`, `language`, `source`, `period`, `date_recorded`, `keywords`, `location`, `location_is_sensitive`, `visibility`, `status`, `is_sacred`, `consent_status`, `consent_given_by`, `consent_date`, `consent_notes`, `created_by`, `updated_by`, `approved_by`, `approved_at`, `published_at`, `legacy_source`, `legacy_id`, `created_at`, `updated_at`) VALUES (9, 'Clay', 7, NULL, 'Natural earth material used for pottery and sculpture. Different regions have distinct clay types with unique properties.\n\nTraditional uses: Pottery, sculpture, building materials', 'Represents the earth and our connection to the land. Pottery-making is often a communal activity.', NULL, NULL, NULL, NULL, NULL, 'Traditional material, Pottery, sculpture, building materials', NULL, 1, 'public', 'published', 0, 'pending', NULL, NULL, 'Migrated from the earlier public portal, where it was already publicly displayed. Community consent has not been documented yet; please review and update.', NULL, NULL, NULL, NULL, '2026-09-07 08:41:19', 'materials', 3, '2026-09-07 08:41:19', '2026-10-13 23:50:56');
INSERT IGNORE INTO `heritage_records` (`id`, `title`, `category_id`, `summary`, `description`, `cultural_significance`, `community`, `language`, `source`, `period`, `date_recorded`, `keywords`, `location`, `location_is_sensitive`, `visibility`, `status`, `is_sacred`, `consent_status`, `consent_given_by`, `consent_date`, `consent_notes`, `created_by`, `updated_by`, `approved_by`, `approved_at`, `published_at`, `legacy_source`, `legacy_id`, `created_at`, `updated_at`) VALUES (10, 'The Legend of the Sacred Mountain', 2, NULL, 'Long ago, when the world was young, there lived a great warrior who protected his people from harm. The gods, impressed by his courage and wisdom, transformed him into a mountain that would forever watch over the land. To this day, the indigenous people believe the mountain is their eternal guardian.', NULL, 'Northern Highlands', NULL, 'Elder Maria Santos', NULL, NULL, 'Legend', NULL, 1, 'public', 'published', 0, 'pending', NULL, NULL, 'Migrated from the earlier public portal, where it was already publicly displayed. Community consent has not been documented yet; please review and update.', NULL, NULL, NULL, NULL, '2026-09-07 08:41:19', 'stories', 1, '2026-09-07 08:41:19', '2026-10-13 23:50:56');
INSERT IGNORE INTO `heritage_records` (`id`, `title`, `category_id`, `summary`, `description`, `cultural_significance`, `community`, `language`, `source`, `period`, `date_recorded`, `keywords`, `location`, `location_is_sensitive`, `visibility`, `status`, `is_sacred`, `consent_status`, `consent_given_by`, `consent_date`, `consent_notes`, `created_by`, `updated_by`, `approved_by`, `approved_at`, `published_at`, `legacy_source`, `legacy_id`, `created_at`, `updated_at`) VALUES (11, 'The First Weaver', 2, NULL, 'In the beginning, the people had no knowledge of weaving. One day, a spider appeared to a young woman in a dream and taught her the intricate patterns of weaving. When she awoke, she remembered everything and taught her people. This is why indigenous weavers always honor the spider in their work.', NULL, 'Central Valley', NULL, 'Chief Juan dela Cruz', NULL, NULL, 'Myth', NULL, 1, 'public', 'published', 0, 'pending', NULL, NULL, 'Migrated from the earlier public portal, where it was already publicly displayed. Community consent has not been documented yet; please review and update.', NULL, NULL, NULL, NULL, '2026-09-07 08:41:19', 'stories', 2, '2026-09-07 08:41:19', '2026-10-13 23:50:56');
