INSERT IGNORE INTO `stories` (`id`, `title`, `content`, `author`, `category`, `origin`, `image`, `created_at`, `updated_at`) VALUES (3, 'The River\'s Gift', 'During a great drought, the river dried up and the people suffered. A young girl prayed to the water spirits for help. In response, the spirits taught the people how to find hidden springs and preserve water. The river returned, and the community learned the importance of respecting and protecting water sources.', 'Storyteller Pedro Reyes', 'Folk Tale', 'River Communities', 'river.jpg', '2026-09-07 08:41:19', '2026-09-07 08:41:19');
